17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Map;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /**
61	     * Pragmatic check for a syntactically valid email address: a non-empty local
62	     * part, a single '@', and a domain with at least one dot-separated label.
63	     */
64	    private static final Pattern EMAIL_PATTERN =
65	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
66	
67	    /**
68	     * Common street-type abbreviations expanded during address normalization,
69	     * keyed by their upper-cased form.
70	     */
71	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
72	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper) {
86	        this.clinicService = clinicService;
87	        this.ownerMapper = ownerMapper;
88	        this.petMapper = petMapper;
89	        this.visitMapper = visitMapper;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        // Validate & normalize the optional email; reject the create when it is present but invalid.
121	        if (!normalizeEmail(ownerFieldsDto)) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
125	        // abbreviations) and store the normalized form back on the DTO so it is what gets
126	        // persisted and compared. Reject the create when the address is blank once normalized.
127	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
128	        if (canonicalAddress.isBlank()) {
129	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
130	        }
131	        ownerFieldsDto.setAddress(canonicalAddress);
132	        // Reject the create when the owner's city is already at capacity, i.e. it already
133	        // contains 50 or more owners (compared case-insensitively).
134	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
138	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
139	        if (normalizedTelephone == null) {
140	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
141	        }
142	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
143	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
144	            .map(Owner::getTelephone)
145	            .map(OwnerRestControllerV1::toE164)
146	            .filter(existing -> existing != null)
147	            .anyMatch(normalizedTelephone::equals);
148	        if (telephoneInUse) {
149	            return new ResponseEntity<>(HttpStatus.CONFLICT);
150	        }
151	        // Reject the create when another owner already shares this owner's last name and address
152	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
153	        // sharing a household.
154	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
155	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
156	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
157	            boolean householdInUse = this.clinicService.findAllOwners().stream()
158	                .anyMatch(existing ->
159	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
160	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
161	            if (householdInUse) {
162	                return new ResponseEntity<>(HttpStatus.CONFLICT);
163	            }
164	        }
165	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
166	        // owners have already been registered today (by registrationDate).
167	        if (countOwnersRegisteredToday() >= 100) {
168	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
169	        }
170	        ownerFieldsDto.setTelephone(normalizedTelephone);
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        // Default the registration date to the server's current date when none was supplied.
174	        if (owner.getRegistrationDate() == null) {
175	            owner.setRegistrationDate(LocalDate.now());
176	        }
177	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
178	        // letters of the city, the upper-cased first three letters of the last name, and a
179	        // per-city 4-digit sequence one greater than the number of owners already in that city.
180	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
181	        // Record how many existing owners already share this owner's first and last name
182	        // (compared case-insensitively) at the moment before this owner is created.
183	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
184	        this.clinicService.saveOwner(owner);
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    /**
192	     * Validate and normalize the optional owner email in place.
193	     *
194	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
195	     * When present it must be a syntactically valid address; a valid address is
196	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
197	     * present but syntactically invalid, so the caller can reject with 400.
198	     */
199	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
200	        String email = ownerFieldsDto.getEmail();
201	        if (email == null || email.isBlank()) {
202	            ownerFieldsDto.setEmail(null);
203	            return true;
204	        }
205	        String normalized = email.trim().toLowerCase(Locale.ROOT);
206	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
207	            return false;
208	        }
209	        ownerFieldsDto.setEmail(normalized);
210	        return true;
211	    }
212	
213	    /**
214	     * Normalize an owner address: trim, collapse each run of whitespace to a single
215	     * space, upper-case, and expand common street-type abbreviations
216	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
217	     * A {@code null} value normalizes to the empty string.
218	     */
219	    private static String normalizeAddress(String value) {
220	        if (value == null) {
221	            return "";
222	        }
223	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
224	        if (collapsed.isEmpty()) {
225	            return "";
226	        }
227	        String[] tokens = collapsed.split(" ");
228	        StringBuilder sb = new StringBuilder(collapsed.length());
229	        for (int i = 0; i < tokens.length; i++) {
230	            if (i > 0) {
231	                sb.append(' ');
232	            }
233	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
234	        }
235	        return sb.toString();
236	    }
237	
238	    /**
239	     * Normalize an owner household field (last name or address) for duplicate detection:
240	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
241	     * A {@code null} value normalizes to the empty string.
242	     */
243	    private static String normalizeHouseholdKey(String value) {
244	        if (value == null) {
245	            return "";
246	        }
247	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
248	    }
249	
250	    /**
251	     * Normalize a telephone number to E.164 form.
252	     *
253	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
254	     * explicit leading {@code '+'} and country code it is kept; otherwise the
255	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
256	     * dropped from the national digits. The result must contain 8 to 15 digits
257	     * after the {@code '+'}.
258	     *
259	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
260	     *         the input is absent or cannot form a valid E.164 number.
261	     */
262	    private static String toE164(String raw) {
263	        if (raw == null) {
264	            return null;
265	        }
266	        String trimmed = raw.trim();
267	        boolean hasCountryCode = trimmed.startsWith("+");
268	        // Strip spaces, dashes and brackets.
269	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
270	        String digits;
271	        if (hasCountryCode) {
272	            // Keep the explicit country code; drop the leading '+' for validation.
273	            digits = stripped.substring(1);
274	        } else {
275	            // No country code: assume '+61' and drop a single leading '0'.
276	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
277	            digits = "61" + national;
278	        }
279	        if (!digits.matches("\\d{8,15}")) {
280	            return null;
281	        }
282	        return "+" + digits;
283	    }
284	
285	    /**
286	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
287	     *
288	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
289	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
290	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
291	     * equal to one more than the number of owners already in that city
292	     * (e.g. {@code 'SYD-SMI-0007'}).
293	     */
294	    /**
295	     * Count the existing owners whose first and last name match the given names,
296	     * compared case-insensitively. Used to record an owner's namesake count at the
297	     * moment before it is created.
298	     */
299	    private int countNamesakes(String firstName, String lastName) {
300	        return (int) this.clinicService.findAllOwners().stream()
301	            .filter(existing -> existing.getFirstName() != null
302	                && existing.getFirstName().equalsIgnoreCase(firstName)
303	                && existing.getLastName() != null
304	                && existing.getLastName().equalsIgnoreCase(lastName))
305	            .count();
306	    }
307	
308	    private String nextCustomerCode(String city, String lastName) {
309	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
310	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
311	        int sequence = countOwnersInCity(city) + 1;
312	        return String.format("%s-%s-%04d", city3, last3, sequence);
313	    }
314	
315	    /**
316	     * Count the existing owners located in the given city, compared case-insensitively.
317	     * Used to derive the per-city 4-digit sequence in the customer code.
318	     */
319	    private int countOwnersInCity(String city) {
320	        return (int) this.clinicService.findAllOwners().stream()
321	            .filter(existing -> existing.getCity() != null
322	                && existing.getCity().equalsIgnoreCase(city))
323	            .count();
324	    }
325	
326	    /**
327	     * Count the existing owners whose registration date is the server's current date.
328	     * Used to enforce the per-day sign-up limit.
329	     */
330	    private int countOwnersRegisteredToday() {
331	        LocalDate today = LocalDate.now();
332	        return (int) this.clinicService.findAllOwners().stream()
333	            .filter(existing -> today.equals(existing.getRegistrationDate()))
334	            .count();
335	    }
336	
337	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
338	    @Override
339	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
340	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
341	        if (currentOwner == null) {
342	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
343	        }
344	        if (!normalizeEmail(ownerFieldsDto)) {
345	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
346	        }
347	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
348	        if (normalizedTelephone == null) {
349	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
350	        }
351	        currentOwner.setAddress(ownerFieldsDto.getAddress());
352	        currentOwner.setCity(ownerFieldsDto.getCity());
353	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
354	        currentOwner.setLastName(ownerFieldsDto.getLastName());
355	        currentOwner.setTelephone(normalizedTelephone);
356	        currentOwner.setEmail(ownerFieldsDto.getEmail());
357	        this.clinicService.saveOwner(currentOwner);
358	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Transactional
363	    @Override
364	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
365	        Owner owner = this.clinicService.findOwnerById(ownerId);
366	        if (owner == null) {
367	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
368	        }
369	        this.clinicService.deleteOwner(owner);
370	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
371	    }
372	
373	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
374	    @Override
375	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
376	        Owner owner = this.clinicService.findOwnerById(ownerId);
377	        if (owner == null) {
378	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
379	        }
380	        HttpHeaders headers = new HttpHeaders();
381	        Pet pet = petMapper.toPet(petFieldsDto);
382	        owner.setId(ownerId);
383	        pet.setOwner(owner);
384	        pet.getType().setName(null);
385	        this.clinicService.savePet(pet);
386	        PetDto petDto = petMapper.toPetDto(pet);
387	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
388	            .buildAndExpand(pet.getId()).toUri());
389	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
390	    }
391	
392	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
393	    @Override
394	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
395	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
396	        if (currentOwner != null) {
397	            Pet currentPet = this.clinicService.findPetById(petId);
398	            if (currentPet != null) {
399	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
400	                currentPet.setName(petFieldsDto.getName());
401	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
402	                this.clinicService.savePet(currentPet);
403	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
404	            }
405	        }
406	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
407	    }
408	
409	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
410	    @Override
411	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
412	        HttpHeaders headers = new HttpHeaders();
413	        Visit visit = visitMapper.toVisit(visitFieldsDto);
414	        Pet pet = new Pet();
415	        pet.setId(petId);
416	        visit.setPet(pet);
417	        this.clinicService.saveVisit(visit);
418	        VisitDto visitDto = visitMapper.toVisitDto(visit);
419	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
420	            .buildAndExpand(visit.getId()).toUri());
421	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
422	    }
423	
424	
425	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
426	    @Override
427	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
